import os
import glob

# Check for all files including hidden ones
print("All files in /app (including hidden):")
for item in sorted(os.listdir('/app')):
    path = f'/app/{item}'
    if os.path.isfile(path):
        size = os.path.getsize(path)
        print(f"  {item}: {size} bytes")

# Check for backup files with various patterns
print("\nSearching for backup/recovery files:")
patterns = ['*.bak', '*.backup', '*.old', '*~', '*.wal-*', '*.db-shm', '*.db-journal', '.*.db*']
for pattern in patterns:
    matches = glob.glob(f'/app/{pattern}')
    if matches:
        print(f"  Found with pattern '{pattern}':", matches)

# Check parent directory too
print("\nFiles in parent directory:")
try:
    for item in os.listdir('/'):
        if 'app' in item.lower() or 'backup' in item.lower() or 'recover' in item.lower():
